//! Proof that `EnrollmentClient::check_enrollment_status` round-trips ADR-0122's
//! `CheckEnrollmentStatus` RPC over real gRPC, narrowing
//! `gaps.d/ackplane-client-cannot-detect-unenrolled-repositories.md`: this
//! crate can now ask the question, even though sourcing a repository's own
//! candidate identity for the ask remains separate, undecided work.
//!
//! Skipped unless `ACKPLANE_TEST_DATABASE_URL` names the gated test
//! PostgreSQL database. Starts a real `NodeEnrollmentService` on an
//! ephemeral loopback port, mirroring `tests/enrollment_and_sync.rs`.

use ackplane_client::{EnrollmentClient, EnrollmentState, EnrollmentStatusAuthentication};
use ackplane_protocol::v1::{
    self, node_enrollment_service_client::NodeEnrollmentServiceClient,
    node_enrollment_service_server::NodeEnrollmentServiceServer,
};
use ackplane_server::{
    enrollment::{activation_challenge_bytes, public_key_fingerprint},
    enrollment_service::NodeEnrollmentService,
    enrollment_store::{EnrollmentApproval, EnrollmentStore},
};
use ed25519_dalek::{Signer, SigningKey};
use tokio::sync::oneshot;
use tokio_stream::wrappers::TcpListenerStream;
use tonic::{transport::Server, Request};

fn unique_id(label: &str) -> String {
    let nanos = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap()
        .as_nanos();
    format!("ackplane-client-check-status-{label}-{nanos}")
}

fn now_rfc3339() -> String {
    time::OffsetDateTime::now_utc()
        .format(&time::format_description::well_known::Rfc3339)
        .unwrap()
}

struct RunningService {
    endpoint: String,
    shutdown: oneshot::Sender<()>,
    handle: tokio::task::JoinHandle<()>,
}

async fn start_enrollment_service(database_url: &str) -> RunningService {
    let store = EnrollmentStore::connect(database_url)
        .await
        .expect("the gated test database should accept enrollment migrations");
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
        .await
        .expect("the test service should bind loopback");
    let address = listener.local_addr().unwrap();
    let (shutdown_tx, shutdown_rx) = oneshot::channel();
    let handle = tokio::spawn(async move {
        Server::builder()
            .add_service(NodeEnrollmentServiceServer::new(
                NodeEnrollmentService::new(store),
            ))
            .serve_with_incoming_shutdown(TcpListenerStream::new(listener), async {
                let _ = shutdown_rx.await;
            })
            .await
            .expect("the test service should run");
    });
    RunningService {
        endpoint: format!("http://{address}"),
        shutdown: shutdown_tx,
        handle,
    }
}

/// Enrolls and activates a fresh node against the given endpoint, returning
/// its identity and signing key for the caller to build a status-check
/// request from.
async fn enroll_and_activate(endpoint: &str) -> (String, String, String, String, SigningKey) {
    let tenant_id = unique_id("tenant");
    let repository_id = unique_id("repository");
    let node_id = unique_id("node");
    let request_id = unique_id("request");
    let signing_key = SigningKey::from_bytes(&[73_u8; 32]);
    let public_key = signing_key.verifying_key().to_bytes().to_vec();
    let fingerprint = public_key_fingerprint(&public_key);

    let mut enrollment_client = NodeEnrollmentServiceClient::connect(endpoint.to_string())
        .await
        .expect("the in-process enrollment service should accept the connection");
    enrollment_client
        .submit_enrollment_request(Request::new(v1::EnrollmentRequest {
            request_id: request_id.clone(),
            tenant_id: tenant_id.clone(),
            repository_id: repository_id.clone(),
            proposed_node_id: node_id.clone(),
            display_name: "test node".to_string(),
            public_key_fingerprint: fingerprint.clone(),
            requested_capabilities: vec!["synchronize".to_string()],
            created_at: now_rfc3339(),
            expires_at: "2030-01-01T00:00:00Z".to_string(),
            public_key: public_key.clone(),
        }))
        .await
        .expect("submit_enrollment_request should round-trip over the wire");

    let database_url =
        std::env::var("ACKPLANE_TEST_DATABASE_URL").expect("already required by the caller");
    let mut store = EnrollmentStore::connect(&database_url)
        .await
        .expect("the gated test database should accept a second enrollment connection");
    store
        .approve(&EnrollmentApproval {
            request_id: request_id.clone(),
            tenant_id: tenant_id.clone(),
            repository_id: repository_id.clone(),
            public_key_fingerprint: fingerprint.clone(),
            approved_capabilities: vec!["synchronize".to_string()],
            approved_by: "test-administrator".to_string(),
        })
        .await
        .expect("approval should succeed for a pending request");

    let challenge = enrollment_client
        .get_activation_challenge(Request::new(v1::EnrollmentChallengeRequest {
            request_id: request_id.clone(),
            tenant_id: tenant_id.clone(),
            repository_id: repository_id.clone(),
            proposed_node_id: node_id.clone(),
            public_key_fingerprint: fingerprint.clone(),
        }))
        .await
        .expect("an approved request should be issued a real activation challenge")
        .into_inner();
    let proof_bytes = activation_challenge_bytes(
        &challenge.nonce,
        &request_id,
        &tenant_id,
        &repository_id,
        &node_id,
        &fingerprint,
    );
    enrollment_client
        .activate_enrollment(Request::new(v1::EnrollmentActivationProof {
            request_id,
            tenant_id: tenant_id.clone(),
            repository_id: repository_id.clone(),
            proposed_node_id: node_id.clone(),
            public_key_fingerprint: fingerprint.clone(),
            nonce: challenge.nonce,
            signature: signing_key.sign(&proof_bytes).to_bytes().to_vec(),
        }))
        .await
        .expect("activation with a genuine proof of possession should succeed");

    (tenant_id, repository_id, node_id, fingerprint, signing_key)
}

fn signed_status_request(
    tenant_id: &str,
    repository_id: &str,
    candidate_node_id: &str,
    candidate_key_fingerprint: &str,
    signing_key: &SigningKey,
) -> v1::EnrollmentStatusRequest {
    let mut authentication = EnrollmentStatusAuthentication {
        node_id: candidate_node_id.to_owned(),
        key_fingerprint: candidate_key_fingerprint.to_owned(),
        signed_at: now_rfc3339(),
        nonce: unique_id("nonce").into_bytes(),
        signature: Vec::new(),
    };
    let bytes = ackplane_protocol::enrollment_status_auth::enrollment_status_signing_bytes(
        tenant_id,
        repository_id,
        ackplane_protocol::enrollment_status_auth::EnrollmentStatusOperation::Check,
        &authentication,
    );
    authentication.signature = signing_key.sign(&bytes).to_bytes().to_vec();
    v1::EnrollmentStatusRequest {
        tenant_id: tenant_id.to_owned(),
        repository_id: repository_id.to_owned(),
        candidate_node_id: candidate_node_id.to_owned(),
        candidate_key_fingerprint: candidate_key_fingerprint.to_owned(),
        authentication: Some(authentication),
    }
}

#[tokio::test]
async fn an_activated_node_can_check_its_own_status_over_real_grpc() {
    let Ok(database_url) = std::env::var("ACKPLANE_TEST_DATABASE_URL") else {
        println!("skipped: ACKPLANE_TEST_DATABASE_URL not set");
        return;
    };
    let service = start_enrollment_service(&database_url).await;
    let (tenant_id, repository_id, node_id, fingerprint, signing_key) =
        enroll_and_activate(&service.endpoint).await;

    let mut client = EnrollmentClient::connect(&service.endpoint)
        .await
        .expect("EnrollmentClient should connect to the in-process service");
    let request = signed_status_request(
        &tenant_id,
        &repository_id,
        &node_id,
        &fingerprint,
        &signing_key,
    );
    let result = client
        .check_enrollment_status(request)
        .await
        .expect("the RPC itself should round-trip over real gRPC");

    assert!(result.verified, "an activated node's own check must verify");
    assert_eq!(result.state(), EnrollmentState::Active);

    let _ = service.shutdown.send(());
    let _ = service.handle.await;
}

#[tokio::test]
async fn a_never_enrolled_candidate_is_reported_as_unverified_over_real_grpc() {
    let Ok(database_url) = std::env::var("ACKPLANE_TEST_DATABASE_URL") else {
        println!("skipped: ACKPLANE_TEST_DATABASE_URL not set");
        return;
    };
    let service = start_enrollment_service(&database_url).await;

    let signing_key = SigningKey::from_bytes(&[201_u8; 32]);
    let tenant_id = unique_id("never-tenant");
    let repository_id = unique_id("never-repository");
    let node_id = unique_id("never-node");
    let fingerprint = unique_id("never-fingerprint");

    let mut client = EnrollmentClient::connect(&service.endpoint)
        .await
        .expect("EnrollmentClient should connect to the in-process service");
    let request = signed_status_request(
        &tenant_id,
        &repository_id,
        &node_id,
        &fingerprint,
        &signing_key,
    );
    let result = client
        .check_enrollment_status(request)
        .await
        .expect("the RPC itself should round-trip even for an unrecognised binding");

    assert!(
        !result.verified,
        "a binding that was never enrolled must not verify"
    );
    assert_eq!(result.state(), EnrollmentState::Unspecified);

    let _ = service.shutdown.send(());
    let _ = service.handle.await;
}
